{

"kind": "propose",
"summary": "Increase probe timeouts to match application startup duration",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Readiness/liveness probes timeout before application responds",
    "supporting": ["probe_timeouts", "probe_kills", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search-api",
    "uid": "uid-deployment-search-api"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    },
    "readiness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Reduce probe failures by aligning timeouts with application response times",
  "rationale": "Logs show the app responds to /ready and /healthz within 15s, but probes timeout at 1s. Increasing timeouts to 5s allows the app to respond before probes fail. No recent rollout (rollout_recent=false) suggests this is not a new version issue. Readiness probe failures (probe_timeouts=true) and liveness kills (probe_kills=true) confirm the app is not crashing but taking longer than allowed to start. No OOM kills (crashed_on_its_own=false) suggest the app is not crashing itself, but rather taking longer than allowed to start. This aligns with 'probe_timeout_too_short'.",
  "cited_evidence_ids": ["probe_timeouts", "probe_kills", "ev-container_logs_tail", "ev-rollout_history", "ev-target_events", "ev-pod_states"],
  "cited_predicates": ["probe_timeouts", "probe_kills", "rollout_recent", "crashed_on_its_own"]
}
}
